extraction_code.extractDraft_function:
function extractDraft(rawData, bracketMatchId) {
  var result = {
    bracket_match_id: bracketMatchId,
    games: []
  };

  if (!rawData || !rawData.data || !rawData.data.length) {
    return result; // bye, forfeit, or not played
  }

  // Get match-level info from data[0]
  var m0 = rawData.data[0];
  result.match_id = m0.id || null;
  result.state = m0.state || null;

  // Extract competitors (team names, players, scores)
  result.competitors = [];
  if (m0.competitors) {
    for (var i = 0; i < m0.competitors.length; i++) {
      var c = m0.competitors[i];
      result.competitors.push({
        number: c.number,
        roster_name: c.roster ? c.roster.name : null,
        seed: c.seed ? c.seed.number : null,
        score: c.result ? c.result.score : null,
        forfeit: c.result ? c.result.forfeit : false,
        is_bye: c.isBye || false,
        players: (c.players || []).map(function(p) { return p.name; })
      });
    }
  }

  // Process ALL data[] entries — one per map/mode
  var gameNum = 0;
  for (var di = 0; di < rawData.data.length; di++) {
    var item = rawData.data[di];

    // Extract per-map bans and picks from teams[]
    var t1Bans = [], t2Bans = [], t1Picks = [], t2Picks = [];
    if (item.teams) {
      for (var ti = 0; ti < item.teams.length; ti++) {
        var t = item.teams[ti];
        var bans = (t.bans || []).map(function(b) { return b.name; });
        var picks = (t.players || [])
          .map(function(p) { return p.brawler ? p.brawler.name : null; })
          .filter(function(n) { return n !== null; });

        if (t.side === 0) {
          t1Bans = bans; t1Picks = picks;
        } else if (t.side === 1) {
          t2Bans = bans; t2Picks = picks;
        }
      }
    }

    // Extract game info — only use games[0] (games[1] is a duplicate)
    if (item.games && item.games.length > 0) {
      var g = item.games[0];
      var loc = g.location || {};
      gameNum++;

      var game = {
        game_num: gameNum,
        map_name: loc.name || null,
        game_mode: loc.gameMode || null,
        team1_bans: t1Bans,
        team2_bans: t2Bans,
        team1_picks: [],
        team2_picks: [],
        team1_won: false,
        team2_won: false
      };

      // Per-game picks and winner from games[0].teams[]
      if (g.teams) {
        for (var gi = 0; gi < g.teams.length; gi++) {
          var gt = g.teams[gi];
          var picks = (gt.players || [])
            .map(function(p) { return p.brawler ? p.brawler.name : null; })
            .filter(function(n) { return n !== null; });

          if (gi === 0) {
            game.team1_picks = picks;
            game.team1_won = gt.isWinner || false;
          } else {
            game.team2_picks = picks;
            game.team2_won = gt.isWinner || false;
          }
        }
      }

      result.games.push(game);
    }
  }

  return result;
}

extraction_code.fetchMatchDraft_function:
async function fetchMatchDraft(matchId) {
  const res = await fetch('/api/match/live/' + matchId);
  const data = await res.json();
  return extractDraft(data, matchId);
}

extraction_code.fetchAllDrafts_function:
async function fetchAllDrafts(matchIds, batchSize, delayMs) {
  var results = [];
  var errors = [];

  for (var i = 0; i < matchIds.length; i += batchSize) {
    var batch = matchIds.slice(i, i + batchSize);
    var promises = batch.map(function(mid) {
      return fetchMatchDraft(mid).catch(function(e) {
        errors.push({ id: mid, error: e.message });
        return null;
      });
    });
    var batchResults = await Promise.all(promises);
    for (var j = 0; j < batchResults.length; j++) {
      if (batchResults[j] !== null) results.push(batchResults[j]);
    }
    await new Promise(function(r) { setTimeout(r, delayMs); });
  }

  return { results: results, errors: errors, total: matchIds.length };
}

