// Step 1: Get the bracket UUID (or use the brackets table above)
var bracketUuid = '179c9838-85da-11f1-9e79-866f44b823f8'; // EMEA QD1

// Step 2: Get all match IDs from the bracket
var bracketRes = await fetch('/api/brackets/data?url=' + bracketUuid);
var bracketData = await bracketRes.json();
var matches = bracketData.data.match;
var matchIds = matches.map(function(m) { return m.id; });

// Step 3: Fetch draft data for all matches (batch of 30, 500ms delay)
var drafts = await fetchAllDrafts(matchIds, 30, 500);

console.log('Results:', drafts.results.length);
console.log('Errors:', drafts.errors.length);
console.log('Total games:', drafts.results.reduce(function(sum, r) {
  return sum + r.games.length;
}, 0));

